        if (match.found) {
            console.log('✅ Found feature branch:', match.branch, '(PR #' + match.prNumber + ')');
            return match.branch;
        }
        console.log('No open PR found for', ticketKey, 'in', featurePR.owner + '/' + featurePR.repo);
    } catch (e) {
        console.warn('Could not list PRs for feature branch lookup:', e);
    }
    return null;
}

